# (xgrammar) to schema.json, so each one parses and matches it.
python3 -m sglang.launch_server --model-path "$MODEL" ${MODEL_REVISION:+--revision "$MODEL_REVISION"} --served-model-name "$MODEL" --context-length "$MAX_MODEL_LEN" --host 127.0.0.1 --port 30000 &
SERVER=$!
