until python3 -c 'import urllib.request; urllib.request.urlopen("http://127.0.0.1:30000/health_generate", timeout=10)' 2>/dev/null; do
  kill -0 "$SERVER" 2>/dev/null || { echo 'sglang server exited before it was ready' >&2; wait "$SERVER"; exit 1; }
  sleep 5
