import concurrent.futures, json, os, sys, urllib.error, urllib.request, uuid

BASE = "http://127.0.0.1:30000"
URLS = ("/v1/chat/completions", "/v1/completions")
LORA = sys.argv[3] if len(sys.argv) > 3 else ""
MODEL = os.environ["MODEL"] + (":" + LORA if LORA else "")
SCHEMA = json.load(open(sys.argv[4])) if len(sys.argv) > 4 else None

def text(body):
    try:
        c = body["choices"][0]
        return c["message"]["content"] if "message" in c else c["text"]
    except (KeyError, IndexError, TypeError):
        return None

def one(line):
    out = {"id": "batch_req_" + uuid.uuid4().hex, "custom_id": None, "response": None, "error": None}
    try:
        req = json.loads(line)
        out["custom_id"] = req.get("custom_id")
    except ValueError as e:
        out["error"] = {"code": "invalid_json", "message": str(e)}
        return out
    if req.get("url") not in URLS:
        out["error"] = {"code": "unsupported_url", "message": "url %r is not one of %s" % (req.get("url"), ", ".join(URLS))}
        return out
    body = dict(req.get("body") or {}, model=MODEL, stream=False)
    if SCHEMA is not None and req["url"] == "/v1/chat/completions":
        body["response_format"] = {"type": "json_schema", "json_schema": {"name": "output", "schema": SCHEMA, "strict": True}}
    elif SCHEMA is not None:
        body["json_schema"] = json.dumps(SCHEMA)
    http = urllib.request.Request(BASE + req["url"], json.dumps(body).encode(), {"Content-Type": "application/json"})
    try:
        with urllib.request.urlopen(http, timeout=3600) as r:
            status, raw = r.status, r.read()
    except urllib.error.HTTPError as e:
        status, raw = e.code, e.read()
    except OSError as e:
        out["error"] = {"code": "request_failed", "message": str(e)}
        return out
    try:
        parsed = json.loads(raw)
    except ValueError:
        parsed = {"raw": raw.decode(errors="replace")}
    if LORA and isinstance(parsed, dict) and "model" in parsed:
        parsed["model"] = LORA
    out["response"] = {"status_code": status, "request_id": out["id"], "body": parsed}
    return out

with open(sys.argv[1]) as f:
    lines = [l for l in f if l.strip()]
ok = parsed = 0
with open(sys.argv[2], "w") as w, concurrent.futures.ThreadPoolExecutor(int(os.environ["CONCURRENCY"])) as pool:
    for res in pool.map(one, lines):
        if res["response"] is not None and res["response"]["status_code"] == 200:
            ok += 1
            try:
                json.loads(text(res["response"]["body"]))
                parsed += 1
            except (TypeError, ValueError):
                pass
        w.write(json.dumps(res) + "\n")
print("%d of %d requests succeeded" % (ok, len(lines)), file=sys.stderr)
if SCHEMA is not None:
    print("%d of %d answers parse as JSON" % (parsed, ok), file=sys.stderr)
PY

